<?php need($pdo,$user,'documents.view');$q=$pdo->prepare("SELECT r.*,(SELECT f.id FROM hr_files f WHERE f.record_id=r.id ORDER BY f.id DESC LIMIT 1) file_id FROM hr_records r WHERE r.module='documents' AND r.employee_id=? ORDER BY r.created_at DESC");$q->execute([$id]);$docs=$q->fetchAll(PDO::FETCH_ASSOC);$editDoc=(int)($_GET['document']??0);$doc=['data'=>'{}'];foreach($docs as $d)if((int)$d['id']===$editDoc)$doc=$d;$dv=array_merge(json_decode($doc['data'],true)?:[],$doc);if($error&&($_POST['action']??'')==='save_document')$dv=$_POST;
?><section class="card table-card"><div class="table-scroll"><table class="directory"><thead><tr><th>Document</th><th>Type</th><th>Issue date</th><th>Expiry</th><th>Actions</th></tr></thead><tbody><?php if(!$docs):?><tr><td colspan="5"><div class="empty-state">No documents uploaded yet.</div></td></tr><?php endif;foreach($docs as $d):$data=json_decode($d['data'],true)?:[];$expiry=$data['expires']??'';?><tr><td><?=h($d['title'])?></td><td><?=h($data['type']??'Other Documents')?></td><td><?=h($data['issued']??'—')?></td><td><?=h($expiry?:'—')?><?php if($expiry&&$expiry<=date('Y-m-d',strtotime('+30 days'))):?><p><?php fbadge($expiry<date('Y-m-d')?'Expired':'Expires soon',false);?></p><?php endif;?></td><td><div class="actions"><?php if($d['file_id']):?><a class="button small" href="document.php?id=<?=$d['file_id']?>">Download</a><?php endif;if($documentEditing&&can($pdo,$user,'documents.edit')):?><a class="button small" href="?page=employee-edit&id=<?=$id?>&tab=documents&document=<?=$d['id']?>">Edit</a><?php endif;if($documentEditing&&can($pdo,$user,'documents.delete')):?><form method="post" data-confirm="Permanently delete this document and its uploaded versions?"><?php ftoken();?><input type="hidden" name="action" value="delete_document"><input type="hidden" name="document_id" value="<?=$d['id']?>"><button class="button small danger">Delete</button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></section>
<?php if($documentEditing&&can($pdo,$user,$editDoc?'documents.edit':'documents.create')):?><section class="card"><div class="card-heading"><h2><?=$editDoc?'Edit':'Upload'?> document</h2></div><form method="post" enctype="multipart/form-data"><?php ftoken();?><input type="hidden" name="action" value="save_document"><input type="hidden" name="employee_id" value="<?=$id?>"><input type="hidden" name="document_id" value="<?=$editDoc?>"><div class="form-grid"><?php field('title','Document title',$dv,'text',true);choose('type','Document type',$dv,$docTypes);field('issued','Issue date',$dv,'date');field('expires','Expiry date',$dv,'date');?><label class="full">File (PDF, JPEG or PNG · up to 4 MB)<input type="file" name="document" accept="application/pdf,image/jpeg,image/png" <?=$editDoc?'':'required'?>></label><label class="full">Notes<textarea name="notes" maxlength="5000"><?=h($dv['notes']??'')?></textarea></label></div><div class="form-actions"><?php if($editDoc):?><a class="button" href="?page=employee-edit&id=<?=$id?>&tab=documents">Cancel edit</a><?php endif;?><button class="button primary">Save document</button></div></form></section><?php endif;?>
